using System;
using Ashfall.Core;
using Ashfall.Modules.WeaponHandling;
using Ashfall.Modules.HealthStates;
using Ashfall.Integration.Playable.HandsWeapons;
static class ArsenalCases
{
 static int count;
 static void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
 static bool Near(float a,float b){return Math.Abs(a-b)<.0002f;}
 sealed class Query:IInteractionQuery{public bool Clear=true;public bool HasLineOfSight(string a,string b,Float3 c,Float3 d,float range){return Clear;}}
 static HandlingInput Input(bool fire=false,bool grip=false,Float3 local=new Float3(),bool left=false){return new HandlingInput{Enabled=true,PrimaryTracked=true,SupportTracked=true,Trigger=fire,Grip=grip,SupportLocal=local,ForegripDistance=1,LeftHanded=left};}
 static R23M1014Pose Pose(){return new R23M1014Pose{Origin=new Float3(),Forward=new Float3(0,0,1),Right=new Float3(1,0,0),Up=new Float3(0,1,0)};}
 static bool Step(R23RoundState round,float dt=0,HandlingInput input=new HandlingInput(),HandlingAction action=HandlingAction.Sample,bool paused=false){if(!input.Enabled)input=Input();return round.StepM1014(dt,input,action,Pose(),false,paused);}
 static R23M1014Volley Fire(R23RoundState round){Step(round,.15f);Step(round,.15f);Check(Step(round,0,Input(true)),"production source M1014 accepts one real discharge");return round.LastM1014Volley;}
 static R23M1014Contact[] Contacts(R23M1014Volley volley,string a,string b=null,float distance=5,bool head=false){var contacts=new R23M1014Contact[8];var directions=volley.Directions;for(int i=0;i<8;i++){var d=directions[i];contacts[i]=new R23M1014Contact(i,b!=null&&i>=4?b:a,new Float3(volley.Origin.X+d.X*distance,volley.Origin.Y+d.Y*distance,volley.Origin.Z+d.Z*distance),head);}return contacts;}
 static int Main(){try{
  var query=new Query();var round=new R23RoundState(new[]{"a","b"},query,true);Check(round.SelectWeapon("m1014")&&round.ActiveCapacity==6&&round.ActiveLoaded==6&&round.ActiveReserve==480,"production round selects real source six-round M1014 and finite480-shell pool");
  var identity=round.M1014;Step(round);Check(Step(round,0,Input(true)),"neutral-armed M1014 source first shot is accepted");var volley=round.LastM1014Volley;Check(volley!=null&&volley.Directions.Length==8&&round.ActiveLoaded==5&&round.ActiveReserve==480,"accepted immutable eight-pellet volley debits ONE real shell only");
  Check(!round.Hit("a",new Float3(),new Float3(0,0,5),false,"m1014"),"shotgun cannot apply a fake single-rifle hit path");
  Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a"))==1&&Near(round.LastTargetDamage("a"),77)&&Near(round.ReadTarget("a").Shield,23)&&round.Hits==1,"eight physical pellet contacts group once into exact77 real Health damage");Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a"))==0&&round.Hits==1,"same accepted source volley cannot apply target damage twice");
  Check(!Step(round,.25f,Input(true))&&round.ActiveLoaded==5,"M1014 held auto trigger respects source.2907166667 cadence");Check(Step(round,R23M1014Definition.Interval-.25f,Input(true))&&round.ActiveLoaded==4,"M1014 next held-trigger discharge follows same actual automatic owner");round.ApplyM1014Contacts(round.LastM1014Volley,new R23M1014Contact[0]);
  round.ResetTarget("a");volley=Fire(round);Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a",head:true))==1&&Near(round.LastTargetDamage("a"),77)&&round.LastTargetHeadshot("a"),"M1014 source body/head total remains77, no invented head multiplier");
  round.ResetTarget("a");round.ResetTarget("b");volley=Fire(round);Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a","b"))==2&&Near(round.LastTargetDamage("a"),38.5f)&&Near(round.LastTargetDamage("b"),38.5f),"one actual volley groups four pellets each into two real targets exactly once");
  round.ResetTarget("a");volley=Fire(round);Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a",distance:25))==1&&Near(round.LastTargetDamage("a"),19.25f),"production real Health uses source25percent falloff at25m");
  round.ResetTarget("a");volley=Fire(round);float shield=round.ReadTarget("a").Shield;query.Clear=false;Check(round.ApplyM1014Contacts(volley,Contacts(volley,"a"))==0&&round.ReadTarget("a").Shield==shield,"actual world occlusion refuses target damage after real shell debit");query.Clear=true;
  var empty=new R23RoundState(new[]{"target"},new Query(),true);empty.SelectWeapon("m1014");Step(empty);for(int i=0;i<6;i++){if(i>0)Step(empty,.25f,Input(true));Check(Step(empty,i==0?0:R23M1014Definition.Interval-.25f,Input(true)),"source actual shell discharge"+i);empty.ApplyM1014Contacts(empty.LastM1014Volley,new R23M1014Contact[0]);}Check(empty.ActiveLoaded==0&&empty.ActiveSnapshot.Phase==ReloadPhase.NeedsMagazine&&empty.ActiveReserve==480,"six native shells empty into actual source UP-pack reload, no fake reserve debit");
  var offer=R23M1014Definition.Offer;var socket=R23M1014Definition.Socket;Step(empty,0,Input(false,false,offer));Step(empty,0,Input(false,true,offer));Check(empty.M1014.ReloadGripInProgress&&empty.ActiveReserve==480,"fresh source pack contact claims actual support hand without spending shells");Step(empty,0,Input(false,true,new Float3(offer.X,offer.Y+.05f,offer.Z)));Check(empty.ActiveSnapshot.Phase==ReloadPhase.NeedsMagazine&&empty.ActiveReserve==480,"short UP stroke cannot seat or mint pack ammunition");Step(empty,0,Input(false,true,socket));Check(empty.ActiveSnapshot.Phase==ReloadPhase.NeedsRack&&empty.ActiveLoaded==6&&empty.ActiveSnapshot.Loaded==0&&empty.ActiveSnapshot.Seated==6&&empty.ActiveReserve==474,"completed UP pack moves six real finite shells into native seated state");
  var handle=new Float3(-.06f,.045f,.10f);Step(empty,0,Input(false,true,handle,true));Step(empty,0,Input(false,true,new Float3(handle.X,handle.Y,handle.Z-.09f),true));Check(empty.ActiveSnapshot.Phase==ReloadPhase.NeedsRack,"M1014 BACK handle cannot be acquired with stale pack grip");Step(empty,0,Input(false,false,handle,true));Step(empty,0,Input(false,true,handle,true));Step(empty,.12f,Input(false,true,new Float3(handle.X,handle.Y,handle.Z-.086f),true));Check(empty.ActiveSnapshot.Phase==ReloadPhase.Ready&&empty.ActiveSnapshot.Chambered&&empty.ActiveSnapshot.Loaded==6&&empty.ActiveReserve==474&&!empty.M1014.ReloadGripInProgress,"actual mirrored left-primary fresh BACK stroke chambers existing six shells");
  var retainedShotgun=empty.M1014;empty.SelectWeapon("cx4");empty.SelectWeapon("m1014");Check(object.ReferenceEquals(empty.M1014,retainedShotgun)&&empty.ActiveLoaded==6&&empty.ActiveReserve==474&&empty.ActiveInstanceId=="r23-loadout/m1014","equip round trip preserves exact shotgun owner, seated/loaded state and finite reserve");
  var blockedRound=new R23RoundState(new[]{"target"},new Query(),true);blockedRound.SelectWeapon("m1014");volley=Fire(blockedRound);Check(blockedRound.ApplyM1014Contacts(volley,Contacts(volley,"target"),true)==0&&blockedRound.ActiveLoaded==5&&blockedRound.ReadTarget("target").Shield==100,"XR head-to-muzzle blockage consumes actual discharge but denies all pellet target damage");Check(blockedRound.ApplyM1014Contacts(volley,Contacts(volley,"target"))==0,"blocked discharge cannot be retried after obstruction clears");
  volley=Fire(blockedRound);var duplicate=Contacts(volley,"target");duplicate[7]=duplicate[0];Check(blockedRound.ApplyM1014Contacts(volley,duplicate)==0&&blockedRound.ReadTarget("target").Shield==100,"duplicate pellet evidence cannot multiply one source volley or partially apply groups");
  volley=Fire(blockedRound);Check(blockedRound.ApplyM1014Contacts(volley,Contacts(volley,"target",distance:41))==0,"production M1014 never damages beyond actual40m pellet range");
  int loaded=blockedRound.ActiveLoaded;float cooldown=blockedRound.ActiveSnapshot.CooldownSeconds;Step(blockedRound,.25f,Input(true),paused:true);Check(blockedRound.ActiveLoaded==loaded&&blockedRound.ActiveSnapshot.CooldownSeconds==cooldown&&!Step(blockedRound,.25f,Input(true)),"pause freezes M1014 real owner and requires trigger release on resume");
  var old=blockedRound.M1014;blockedRound.Reset();R23M1014Volley rejected;var input=Input(true);input.Sequence=1000;input.DeltaSeconds=.1f;Check(!old.Apply(new CommandContext("r23-player","player","stale",1000,0,true),HandlingAction.Sample,input,Pose(),out rejected).Accepted&&rejected==null,"round restart retires previous actual shotgun owner instead of allowing stale fire");Check(blockedRound.ActiveLoaded==6&&blockedRound.ActiveReserve==480&&blockedRound.M1014!=old,"explicit round restart regrants source six-shell starter and finite shell pool only once");
  var partiallyHeld=new R23HandInput(true,false,.54f,0,gripPressed:true);Check(!R23WeaponPickupRules.GripNeutral(partiallyHeld)&&!R23WeaponPickupRules.GripClaim(partiallyHeld),"world grip cannot rearm or claim at partially relaxed.54 even if support button stays down");Check(R23WeaponPickupRules.GripNeutral(new R23HandInput(true,false,.2f,0))&&!R23WeaponPickupRules.GripClaim(new R23HandInput(true,false,.64f,0))&&R23WeaponPickupRules.GripClaim(new R23HandInput(true,false,.65f,0)),"source world neutral<=.2 and fresh>=.65 remain distinct from.55 support grip");var digital=new R23HandInput(true,false,0,0,gripPressed:true);Check(R23WeaponPickupRules.GripClaim(digital)&&!R23WeaponPickupRules.GripNeutral(digital),"legacy digital-only controller fallback claims once and stays down until release");
  Check(identity.InstanceId==round.M1014.InstanceId&&round.ReadReserve("px4")==1200&&round.ReadReserve("cx4")==2400,"shotgun shell spending never borrows pistol/rifle reserve or changes source logical identity");
  Console.WriteLine(count+" production arsenal/real-health/grouped-pellet cases passed");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
